// OrbitTweak API – Cloudflare Worker + D1
// Access codes (generated by admins) are bound to the first PC (HWID hash) that redeems them.
// Code holders can add mods to the library; entries from editors wait for admin approval.

const JSONH = { 'content-type': 'application/json; charset=utf-8', 'access-control-allow-origin': '*', 'access-control-allow-headers': 'authorization, content-type', 'access-control-allow-methods': 'GET, POST, OPTIONS' };
const json = (data, status = 200) => new Response(JSON.stringify(data), { status, headers: JSONH });
const err = (msg, status = 400) => json({ error: msg }, status);
const now = () => Math.floor(Date.now() / 1000);
const CATS = ['reshade', 'kill', 'minimap', 'gfx', 'sound', 'other'];
const TOKEN_DAYS = 30;

// ---------- helpers ----------
const b64u = buf => btoa(String.fromCharCode(...new Uint8Array(buf))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const b64uStr = s => b64u(new TextEncoder().encode(s));
const unb64u = s => new TextDecoder().decode(Uint8Array.from(atob(s.replace(/-/g, '+').replace(/_/g, '/')), c => c.charCodeAt(0)));

async function hmac(secret, msg) {
  const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return b64u(await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(msg)));
}
async function makeToken(env, code, hwid, role) {
  const body = b64uStr(JSON.stringify({ c: code, h: hwid, r: role, e: now() + TOKEN_DAYS * 86400 }));
  return body + '.' + await hmac(env.TOKEN_SECRET, body);
}
function newCode() {
  const A = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789', r = crypto.getRandomValues(new Uint8Array(12));
  const s = [...r].map(v => A[v % A.length]).join('');
  return `ORB-${s.slice(0, 4)}-${s.slice(4, 8)}-${s.slice(8, 12)}`;
}
const validHwid = h => typeof h === 'string' && /^[a-f0-9]{64}$/.test(h);
const clean = (s, max) => (typeof s === 'string' ? s : '').replace(/[\u0000-\u001f]/g, ' ').trim().slice(0, max);

/** Resolves the caller from "Authorization: Bearer <token>" + "X-HWID". */
async function auth(req, env) {
  const t = (req.headers.get('authorization') || '').replace(/^Bearer\s+/i, '');
  const hwid = req.headers.get('x-hwid') || '';
  const [body, sig] = t.split('.');
  if (!body || !sig || sig !== await hmac(env.TOKEN_SECRET, body)) return null;
  let p; try { p = JSON.parse(unb64u(body)); } catch { return null; }
  if (!p.e || p.e < now() || p.h !== hwid) return null;
  const row = await env.DB.prepare('SELECT code, role, hwid, revoked, note FROM codes WHERE code = ?').bind(p.c).first();
  if (!row || row.revoked || row.hwid !== hwid) return null;
  await env.DB.prepare('UPDATE codes SET last_seen = ? WHERE code = ?').bind(now(), row.code).run();
  return row;
}

/** Downloads the file once to check type and to compute size + sha256 (streamed). */
async function inspect(url) {
  const r = await fetch(url, { redirect: 'follow', headers: { 'user-agent': 'OrbitTweak-API' } });
  if (!r.ok || !r.body) throw new Error(`Download nicht erreichbar (HTTP ${r.status})`);
  const ds = new crypto.DigestStream('SHA-256');
  let size = 0, head = null;
  const reader = r.body.getReader(), writer = ds.getWriter();
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    if (!head) head = value.slice(0, 8);
    size += value.byteLength;
    if (size > 1024 * 1024 * 1024) throw new Error('Datei größer als 1 GB');
    await writer.write(value);
  }
  await writer.close();
  const hex = [...new Uint8Array(await ds.digest)].map(b => b.toString(16).padStart(2, '0')).join('');
  const sig = head ? String.fromCharCode(...head.slice(0, 4)) : '';
  const kind = sig.startsWith('PK') ? 'zip' : sig === 'RPF7' || sig === '7FPR' ? 'rpf' : sig.startsWith('Rar!') ? 'rar' : head && head[0] === 0x37 && head[1] === 0x7A ? '7z' : null;
  if (!kind) throw new Error('Link liefert keine Mod-Datei (.rpf, .zip, .rar oder .7z)');
  return { size, sha256: hex, kind };
}

function modFromRow(row) {
  const d = JSON.parse(row.data);
  return { ...d, status: row.status, addedBy: row.added_by ? row.added_by.slice(0, 8) + '…' : null, created: row.created_at };
}

// ---------- routes ----------
export default {
  async fetch(req, env) {
    if (req.method === 'OPTIONS') return new Response(null, { headers: JSONH });
    const url = new URL(req.url), path = url.pathname.replace(/\/+$/, '');
    let body = {};
    if (req.method === 'POST') { try { body = await req.json(); } catch { return err('Ungültige Anfrage'); } }

    try {
      // public: live library
      if (path === '/api/mods' && req.method === 'GET') {
        const { results } = await env.DB.prepare("SELECT * FROM mods WHERE status = 'live' ORDER BY created_at DESC").all();
        return json({ mods: results.map(modFromRow) });
      }

      // redeem a code -> bind to this PC
      if (path === '/api/redeem' && req.method === 'POST') {
        const code = clean(body.code, 32).toUpperCase(), hwid = body.hwid;
        if (!/^ORB-[A-Z0-9]{4}-[A-Z0-9]{4}-[A-Z0-9]{4}$/.test(code)) return err('Code-Format ungültig');
        if (!validHwid(hwid)) return err('HWID ungültig');
        const row = await env.DB.prepare('SELECT * FROM codes WHERE code = ?').bind(code).first();
        if (!row || row.revoked) return err('Code ungültig oder gesperrt', 403);
        if (row.hwid && row.hwid !== hwid) return err('Dieser Code ist schon an einen anderen PC gebunden', 403);
        if (!row.hwid) await env.DB.prepare('UPDATE codes SET hwid = ?, bound_at = ? WHERE code = ? AND hwid IS NULL').bind(hwid, now(), code).run();
        return json({ token: await makeToken(env, code, hwid, row.role), role: row.role, note: row.note });
      }

      const me = await auth(req, env);
      if (path === '/api/me') return me ? json({ role: me.role, note: me.note, code: me.code.slice(0, 8) + '-••••-••••' }) : err('Nicht angemeldet', 401);
      if (!me) return err('Nicht angemeldet', 401);
      const admin = me.role === 'admin';

      // ----- mods -----
      if (path === '/api/mods' && req.method === 'POST') {
        const name = clean(body.name, 60), cat = CATS.includes(body.cat) ? body.cat : 'other', link = clean(body.url, 600);
        if (name.length < 3) return err('Name zu kurz');
        if (!/^https:\/\/[^\s]+$/i.test(link)) return err('Download-Link muss mit https:// beginnen');
        const img = clean(body.img, 600);
        if (img && !/^https:\/\/[^\s]+$/i.test(img)) return err('Vorschaubild-Link muss mit https:// beginnen');
        const info = await inspect(link);
        const id = 'm-' + crypto.randomUUID().slice(0, 8);
        const entry = {
          id, type: 'file', name, cat, url: link, img: img || undefined, sha256: info.sha256, size: info.size,
          author: clean(body.author, 40) || 'Community', desc: clean(body.desc, 240),
          tags: (Array.isArray(body.tags) ? body.tags : String(body.tags || '').split(',')).map(t => clean(t, 20).toLowerCase()).filter(Boolean).slice(0, 6),
          popular: Math.max(0, Math.min(100, parseInt(body.popular) || 50)), added: new Date().toISOString().slice(0, 10)
        };
        const status = admin ? 'live' : 'pending';
        await env.DB.prepare('INSERT INTO mods (id, data, status, added_by, created_at) VALUES (?, ?, ?, ?, ?)').bind(id, JSON.stringify(entry), status, me.code, now()).run();
        return json({ id, status, size: info.size, sha256: info.sha256 });
      }
      if (path === '/api/mods/mine') {
        const { results } = await env.DB.prepare('SELECT * FROM mods WHERE added_by = ? ORDER BY created_at DESC').bind(me.code).all();
        return json({ mods: results.map(modFromRow) });
      }
      if (path === '/api/mods/delete' && req.method === 'POST') {
        const row = await env.DB.prepare('SELECT * FROM mods WHERE id = ?').bind(clean(body.id, 20)).first();
        if (!row) return err('Nicht gefunden', 404);
        if (!admin && !(row.added_by === me.code && row.status === 'pending')) return err('Keine Berechtigung', 403);
        await env.DB.prepare('DELETE FROM mods WHERE id = ?').bind(row.id).run();
        return json({ ok: true });
      }

      // ----- admin only -----
      if (!admin) return err('Nur für Admins', 403);
      if (path === '/api/mods/pending') {
        const { results } = await env.DB.prepare("SELECT * FROM mods WHERE status = 'pending' ORDER BY created_at").all();
        return json({ mods: results.map(modFromRow) });
      }
      if (path === '/api/mods/approve' && req.method === 'POST') {
        await env.DB.prepare("UPDATE mods SET status = 'live' WHERE id = ?").bind(clean(body.id, 20)).run();
        return json({ ok: true });
      }
      if (path === '/api/codes' && req.method === 'GET') {
        const { results } = await env.DB.prepare('SELECT code, role, note, hwid, created_at, bound_at, last_seen, revoked FROM codes ORDER BY created_at DESC').all();
        return json({ codes: results.map(c => ({ ...c, hwid: c.hwid ? c.hwid.slice(0, 10) : null, self: c.code === me.code })) });
      }
      if (path === '/api/codes' && req.method === 'POST') {
        const role = body.role === 'admin' ? 'admin' : 'editor';
        const code = newCode();
        await env.DB.prepare('INSERT INTO codes (code, role, note, created_at, created_by) VALUES (?, ?, ?, ?, ?)').bind(code, role, clean(body.note, 60), now(), me.code).run();
        return json({ code, role });
      }
      if (path === '/api/codes/revoke' && req.method === 'POST') {
        const code = clean(body.code, 32);
        if (code === me.code) return err('Du kannst deinen eigenen Code nicht sperren');
        await env.DB.prepare('UPDATE codes SET revoked = ? WHERE code = ?').bind(body.undo ? 0 : 1, code).run();
        return json({ ok: true });
      }
      if (path === '/api/codes/unbind' && req.method === 'POST') {
        await env.DB.prepare('UPDATE codes SET hwid = NULL, bound_at = NULL WHERE code = ?').bind(clean(body.code, 32)).run();
        return json({ ok: true });
      }
      return err('Unbekannter Endpunkt', 404);
    } catch (e) {
      return err(e && e.message ? e.message : 'Serverfehler', 500);
    }
  }
};
